// @FIGURE_CODE_BEGIN
/* ── Element spec ────────────────────────────────────────────────────────────
// target camera centre C2        → SphereGeometry(0.11)            black
// target image plane ℓ2          → 4 × unit-cylinder edges (r .022) black  + faint white PlaneGeometry fill
// target optical axis            → cylinder (r .012) black, C2 → plane centre + 0.5·d2
// image point p                  → SphereGeometry(0.12) crimson + BackSide black rim
// back-projection ray C2→P       → dashed pool of cylinders (r .020) black
// scene point P                  → SphereGeometry(0.12) crimson + rim
// reference camera centre C1     → SphereGeometry(0.11)            black
// reference image plane ℓ1       → 4 × cylinder edges + faint fill (same square, 2.4)
// reference optical axis         → cylinder (r .012) black
// image point p'                 → SphereGeometry(0.12) crimson (grey when outside ℓ1) + rim
// projection line P→C1           → dashed cylinders black
// arc p→P / arc P→p' / arc C2→C1 → QuadraticBezierCurve3 → TubeGeometry(r .032) grey + ConeGeometry head
// self-loop at P                 → 280° circular arc TubeGeometry grey + cone, billboarded
// all text                       → addLabel(), bold serif
────────────────────────────────────────────────────────────────────────────── */

const YA = new THREE.Vector3(0, 1, 0);
const COL_BLACK = 0x111111, COL_RED = 0xC0141B, COL_GREY = 0x9A9A9A, COL_OUT = 0x9aa0a6;

const C2 = new THREE.Vector3(-3.4, -1.5, 0.9);
const D2 = new THREE.Vector3(0.55, 0.78, -0.30).normalize();
const FOC = 1.35;      // focal length = plane distance (K = diag(f,f,1))
const HALF = 1.2;      // half side of the 2.4 × 2.4 image square

const state = { px: -0.45, py: 0.55, z: 3.2, yaw: 0, tx: 4.0, tz: -1.2, stage: 3 };

/* ── small helpers ───────────────────────────────────────────────────────── */
function basis(dv) {
  const r = new THREE.Vector3().crossVectors(dv, YA).normalize();
  const u = new THREE.Vector3().crossVectors(r, dv).normalize();
  return { r, u };
}
function M(color, opacity = 1, depthWrite = true) {
  const m = new THREE.MeshBasicMaterial({ color, transparent: true, opacity, depthWrite });
  m.userData.base = opacity;
  return m;
}
const UNIT_CYL = new THREE.CylinderGeometry(1, 1, 1, 10);
UNIT_CYL.translate(0, 0.5, 0);
function segMesh(material, radius) { const m = new THREE.Mesh(UNIT_CYL, material); m.userData.rad = radius; return m; }
function setSeg(m, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
  if (len < 1e-5) { m.visible = false; return; }
  m.visible = true; m.position.copy(a);
  m.quaternion.setFromUnitVectors(YA, dir.divideScalar(len));
  m.scale.set(m.userData.rad, len, m.userData.rad);
}
function makeDash(material, radius, maxN) {
  const g = new THREE.Group(); const arr = [];
  for (let i = 0; i < maxN; i++) { const m = segMesh(material, radius); m.visible = false; g.add(m); arr.push(m); }
  return {
    group: g,
    set(a, b, dash = 0.24, gap = 0.17) {
      const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
      if (len < 1e-5) { arr.forEach(m => m.visible = false); return; }
      dir.divideScalar(len);
      const per = dash + gap, n = Math.max(1, Math.floor((len + gap) / per));
      for (let i = 0; i < arr.length; i++) {
        if (i < n) {
          const s = a.clone().addScaledVector(dir, i * per);
          const e = s.clone().addScaledVector(dir, Math.min(dash, len - i * per));
          setSeg(arr[i], s, e);
        } else arr[i].visible = false;
      }
    }
  };
}
function makeArc(material) {
  const tube = new THREE.Mesh(new THREE.BufferGeometry(), material);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.10, 0.30, 14), material);
  const g = new THREE.Group(); g.add(tube, head);
  return {
    group: g, curve: null,
    set(a0, b0, bulge, trimA = 0.18, trimB = 0.22) {
      const chord = new THREE.Vector3().subVectors(b0, a0);
      const L = chord.length() || 1; chord.divideScalar(L);
      const a = a0.clone().addScaledVector(chord, Math.min(trimA, L * 0.3));
      const b = b0.clone().addScaledVector(chord, -Math.min(trimB, L * 0.3));
      const mid = a.clone().add(b).multiplyScalar(0.5).add(bulge);
      const curve = new THREE.QuadraticBezierCurve3(a, mid, b);
      const pts = []; for (let i = 0; i <= 44; i++) pts.push(curve.getPoint(0.92 * i / 44));
      tube.geometry.dispose();
      tube.geometry = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 44, 0.032, 8, false);
      const tan = curve.getTangent(1).normalize();
      head.position.copy(curve.getPoint(1)).addScaledVector(tan, -0.15);
      head.quaternion.setFromUnitVectors(YA, tan);
      this.curve = curve;
    }
  };
}

/* ── stage groups ────────────────────────────────────────────────────────── */
const gT = new THREE.Group(), gL = new THREE.Group(), gM = new THREE.Group(), gP = new THREE.Group();
scene.add(gT, gL, gM, gP);
const STAGES = [gT, gL, gM, gP];
const stageLabels = [[], [], [], []];

/* ── materials ───────────────────────────────────────────────────────────── */
const matEdge2 = M(COL_BLACK), matEdge1 = M(COL_BLACK);
