/* ── demo ────────────────────────────────────────────────────────────────── */
const steps = [
  { title: 'The measurement p', narration: 'Only the target camera, its image plane ℓ₂ and the measured red point p are active. A single image point is all the sensor gives you.', st: 0, z: 3.2, yaw: 0, tx: 4, tz: -1.2 },
  { title: 'Back-project: P = zK⁻¹p', narration: 'The dashed ray fires out from the camera centre through p. Sliding depth z walks P along that ray — the image alone cannot decide which P is correct.', st: 1, z: 4.4, yaw: 0, tx: 4, tz: -1.2 },
  { title: 'Rigid motion: P’ = MP', narration: 'The loop at P applies M = [R | T], expressing the same 3-D point in the reference camera’s frame. Changing the baseline or yaw changes M, not the point in space.', st: 2, z: 4.4, yaw: 15, tx: 4.6, tz: -1.2 },
