function stopDemo() { playing = false; tween = null; bPlay.textContent = '▶ Play demo'; bPlay.classList.remove('active'); }
document.getElementById('bPrev').addEventListener('click', () => { playing = false; bPlay.textContent = '▶ Play demo'; bPlay.classList.remove('active'); goToStep(stepIdx - 1); });
