// image point p'                 → SphereGeometry(0.13) crimson (grey when outside ℓ1) + rim
// projection line P→C1           → dashed cylinders black
// arc p→P / arc P→p' / arc C2→C1 → QuadraticBezierCurve3 → TubeGeometry(r .034) grey + ConeGeometry head
// self-loop at P                 → ~277° circular arc TubeGeometry grey + cone, billboarded
// all text                       → addLabel(), bold serif (points/planes larger than equations)
────────────────────────────────────────────────────────────────────────────── */

const YA = new THREE.Vector3(0, 1, 0);
const COL_BLACK = 0x111111, COL_RED = 0xC0141B, COL_GREY = 0x9A9A9A, COL_OUT = 0x9aa0a6;

const C2 = new THREE.Vector3(-3.4, -1.5, 0.9);
// principal axis: mostly -Z, only 12.5° above horizontal → the image plane is
// near-vertical and projects as the source's parallelogram.
const D2 = new THREE.Vector3(0.138, 0.217, -0.966).normalize();
const FOC = 1.35;      // focal length = plane distance (K = diag(f,f,1))
const HALF = 1.2;      // half side of the 2.4 × 2.4 image square

const state = { px: -0.45, py: 0.55, z: 5.5, yaw: 20, tx: 2.8, tz: -1.4, stage: 3 };

/* ── small helpers ───────────────────────────────────────────────────────── */
function basis(dv) {
  const r = new THREE.Vector3().crossVectors(dv, YA).normalize();
  const u = new THREE.Vector3().crossVectors(r, dv).normalize();
  return { r, u };
}
function M(color, opacity = 1, o = {}) {
  const m = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity,
    depthTest: false, depthWrite: false,
    side: o.side || THREE.FrontSide
  });
  m.userData.base = opacity;
  return m;
}
function RO(obj, n) { obj.traverse(o => { o.renderOrder = n; }); return obj; }

const UNIT_CYL = new THREE.CylinderGeometry(1, 1, 1, 10);
UNIT_CYL.translate(0, 0.5, 0);
function segMesh(material, radius) { const m = new THREE.Mesh(UNIT_CYL, material); m.userData.rad = radius; return m; }
function setSeg(m, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
  if (len < 1e-5) { m.visible = false; return; }
  m.visible = true; m.position.copy(a);
  m.quaternion.setFromUnitVectors(YA, dir.divideScalar(len));
  m.scale.set(m.userData.rad, len, m.userData.rad);
}
function makeDash(material, radius, maxN) {
  const g = new THREE.Group(); const arr = [];
  for (let i = 0; i < maxN; i++) { const m = segMesh(material, radius); m.visible = false; g.add(m); arr.push(m); }
  return {
    group: g,
    set(a, b, dash = 0.26, gap = 0.19) {
      const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
      if (len < 1e-5) { arr.forEach(m => m.visible = false); return; }
      dir.divideScalar(len);
      const per = dash + gap, n = Math.max(1, Math.floor((len + gap) / per));
      for (let i = 0; i < arr.length; i++) {
        if (i < n) {
          const s = a.clone().addScaledVector(dir, i * per);
          const e = s.clone().addScaledVector(dir, Math.min(dash, len - i * per));
          setSeg(arr[i], s, e);
        } else arr[i].visible = false;
      }
    }
  };
}
function makeArc(material) {
  const tube = new THREE.Mesh(new THREE.BufferGeometry(), material);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.32, 14), material);
  const g = new THREE.Group(); g.add(tube, head);
  return {
    group: g, curve: null,
    set(a0, b0, bulge, trimA = 0.28, trimB = 0.34) {
      const chord = new THREE.Vector3().subVectors(b0, a0);
      const L = chord.length() || 1; chord.divideScalar(L);
      const a = a0.clone().addScaledVector(chord, Math.min(trimA, L * 0.3));
      const b = b0.clone().addScaledVector(chord, -Math.min(trimB, L * 0.3));
      const mid = a.clone().add(b).multiplyScalar(0.5).add(bulge);
      const curve = new THREE.QuadraticBezierCurve3(a, mid, b);
      const pts = []; for (let i = 0; i <= 48; i++) pts.push(curve.getPoint(0.92 * i / 48));
      tube.geometry.dispose();
      tube.geometry = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 48, 0.034, 8, false);
      const tan = curve.getTangent(1).normalize();
      head.position.copy(curve.getPoint(1)).addScaledVector(tan, -0.16);
      head.quaternion.setFromUnitVectors(YA, tan);
      this.curve = curve;
    }
  };
}

/* ── stage groups ────────────────────────────────────────────────────────── */
const gT = new THREE.Group(), gL = new THREE.Group(), gM = new THREE.Group(), gP = new THREE.Group();
scene.add(gT, gL, gM, gP);
const STAGES = [gT, gL, gM, gP];
const stageLabels = [[], [], [], []];

/* ── materials ───────────────────────────────────────────────────────────── */
const matEdge2 = M(COL_BLACK), matEdge1 = M(COL_BLACK);
const matFill2 = M(0xffffff, 0.06, { side: THREE.DoubleSide }), matFill1 = M(0xffffff, 0.06, { side: THREE.DoubleSide });
const matAxis2 = M(COL_BLACK), matAxis1 = M(COL_BLACK);
const matDot = M(COL_BLACK), matDot1 = M(COL_BLACK);
const matRed = M(COL_RED), matRedP = M(COL_RED), matRedPP = M(COL_RED);
const matRim = M(0x000000, 1, { side: THREE.BackSide });
const matRay2 = M(COL_BLACK), matRay1 = M(COL_BLACK);
const matArc1 = M(COL_GREY), matArc3 = M(COL_GREY), matArcRT = M(COL_GREY), matLoop = M(COL_GREY);

/* ── geometry: target frame (stage 0) ────────────────────────────────────── */
const dot2 = new THREE.Mesh(new THREE.SphereGeometry(0.115, 20, 16), matDot); gT.add(dot2);
dot2.position.copy(C2);
const edges2 = [0, 1, 2, 3].map(() => { const m = segMesh(matEdge2, 0.022); gT.add(m); return m; });
const joints2 = [0, 1, 2, 3].map(() => { const m = new THREE.Mesh(new THREE.SphereGeometry(0.022, 8, 6), matEdge2); gT.add(m); return m; });
const fill2 = new THREE.Mesh(new THREE.PlaneGeometry(2 * HALF, 2 * HALF), matFill2); gT.add(fill2);
const axis2 = segMesh(matAxis2, 0.012); gT.add(axis2);
const pDot = new THREE.Mesh(new THREE.SphereGeometry(0.13, 20, 16), matRed); gT.add(pDot);
const pRim = new THREE.Mesh(new THREE.SphereGeometry(0.155, 20, 16), matRim); gT.add(pRim);
const pHit = new THREE.Mesh(new THREE.SphereGeometry(0.32, 12, 10),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false, depthTest: false }));
pHit.material.userData.base = 0; gT.add(pHit);

/* ── geometry: lift to 3-D (stage 1) ─────────────────────────────────────── */
const ray2 = makeDash(matRay2, 0.020, 70); gL.add(ray2.group);
const PDot = new THREE.Mesh(new THREE.SphereGeometry(0.13, 20, 16), matRedP); gL.add(PDot);
const PRim = new THREE.Mesh(new THREE.SphereGeometry(0.155, 20, 16), matRim); gL.add(PRim);
const arcLift = makeArc(matArc1); gL.add(arcLift.group);

/* ── geometry: rigid motion + reference camera (stage 2) ─────────────────── */
const dot1 = new THREE.Mesh(new THREE.SphereGeometry(0.115, 20, 16), matDot1); gM.add(dot1);
const edges1 = [0, 1, 2, 3].map(() => { const m = segMesh(matEdge1, 0.022); gM.add(m); return m; });
const joints1 = [0, 1, 2, 3].map(() => { const m = new THREE.Mesh(new THREE.SphereGeometry(0.022, 8, 6), matEdge1); gM.add(m); return m; });
const fill1 = new THREE.Mesh(new THREE.PlaneGeometry(2 * HALF, 2 * HALF), matFill1); gM.add(fill1);
const axis1 = segMesh(matAxis1, 0.012); gM.add(axis1);
const arcRT = makeArc(matArcRT); gM.add(arcRT.group);

// self-loop above P, built once in its own billboard plane
const loopGroup = new THREE.Group(); gM.add(loopGroup);
{
  const R = 0.6, cy = 0.74, a0 = THREE.MathUtils.degToRad(238), a1 = THREE.MathUtils.degToRad(-40);
  const pts = [];
  for (let i = 0; i <= 64; i++) { const th = a0 + (a1 - a0) * i / 64; pts.push(new THREE.Vector3(R * Math.cos(th), cy + R * Math.sin(th), 0)); }
  const tube = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 64, 0.034, 8, false), matLoop);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.32, 14), matLoop);
  const tan = new THREE.Vector3(Math.sin(a1), -Math.cos(a1), 0).normalize();
  head.position.set(R * Math.cos(a1), cy + R * Math.sin(a1), 0).addScaledVector(tan, 0.06);
  head.quaternion.setFromUnitVectors(YA, tan);
  loopGroup.add(tube, head);
}

/* ── geometry: reprojection (stage 3) ────────────────────────────────────── */
const ray1 = makeDash(matRay1, 0.020, 80); gP.add(ray1.group);
const ppDot = new THREE.Mesh(new THREE.SphereGeometry(0.13, 20, 16), matRedPP); gP.add(ppDot);
const ppRim = new THREE.Mesh(new THREE.SphereGeometry(0.155, 20, 16), matRim); gP.add(ppRim);
const arcProj = makeArc(matArc3); gP.add(arcProj.group);

/* ── draw order (everything depthTest:false → pure painter ordering) ─────── */
RO(fill2, -3); RO(fill1, -3);
RO(arcLift.group, -1); RO(arcProj.group, -1); RO(arcRT.group, -1); RO(loopGroup, -1);
edges2.forEach(m => RO(m, 1)); edges1.forEach(m => RO(m, 1));
joints2.forEach(m => RO(m, 1)); joints1.forEach(m => RO(m, 1));
RO(axis2, 1); RO(axis1, 1);
RO(ray2.group, 2); RO(ray1.group, 2);
RO(pRim, 4); RO(PRim, 4); RO(ppRim, 4);
RO(pDot, 5); RO(PDot, 5); RO(ppDot, 5); RO(dot2, 5); RO(dot1, 5);

/* ── labels ──────────────────────────────────────────────────────────────── */
const SER = t => '<span style="font-family:Georgia,\'Times New Roman\',serif">' + t + '</span>';
const O = new THREE.Vector3();
function L(html, stage, opts) { const e = addLabel(html, O, opts); stageLabels[stage].push(e); return e; }

const lbl_p = L(SER('<b>p</b>'), 0, { fontSize: '23px', offset: [-27, -15] });
const lbl_L2 = L(SER('<i>&#8467;</i><sub>2</sub>'), 0, { fontSize: '25px', offset: [0, 0] });
const lbl_TF = L(SER('Target frame'), 0, { fontSize: '19px', offset: [0, 0] });

const lbl_P = L(SER('<b>P</b>'), 1, { fontSize: '23px', offset: [-27, -16] });
const lbl_lift = L(SER('<b>P</b>=z<b>K</b><sup>-1</sup><b>p</b>'), 1, { fontSize: '16px', offset: [-44, -18] });

const lbl_MP = L(SER('<b>P</b>’=<b>MP</b>'), 2, { fontSize: '16px', offset: [78, 14] });
const lbl_RT = L(SER('<b>R</b>, <b>T</b>'), 2, { fontSize: '16px', offset: [0, 30] });
const lbl_L1 = L(SER('<i>&#8467;</i><sub>1</sub>'), 2, { fontSize: '25px', offset: [0, 0] });
const lbl_RF = L(SER('Reference frame'), 2, { fontSize: '19px', offset: [0, 0] });

const lbl_pp = L(SER('<b>p</b>’'), 3, { fontSize: '23px', offset: [-8, 25] });
const lbl_proj = L(SER('<b>p</b>’=<b>KP</b>'), 3, { fontSize: '16px', offset: [62, -8] });

/* ── the whole chain, recomputed from the controls ───────────────────────── */
const geo = { C1: new THREE.Vector3(), ctr2: new THREE.Vector3(), ctr1: new THREE.Vector3(), b2: null, b1: null, P: new THREE.Vector3(), pW: new THREE.Vector3() };

function corners(c, r, u) {
  return [
    c.clone().addScaledVector(r, -HALF).addScaledVector(u, HALF),
    c.clone().addScaledVector(r, HALF).addScaledVector(u, HALF),
    c.clone().addScaledVector(r, HALF).addScaledVector(u, -HALF),
    c.clone().addScaledVector(r, -HALF).addScaledVector(u, -HALF)
  ];
}
function orient(mesh, r, u, n) {
  mesh.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(r, u, n));
}

function update() {
  const yaw = THREE.MathUtils.degToRad(state.yaw);
  const d1 = D2.clone().applyAxisAngle(YA, yaw);
  const C1 = new THREE.Vector3(C2.x + state.tx, C2.y, C2.z + state.tz);
  const b2 = basis(D2), b1 = basis(d1);
  const ctr2 = C2.clone().addScaledVector(D2, FOC);
  const ctr1 = C1.clone().addScaledVector(d1, FOC);

  // measured image point p (plane coords) and the back-projected 3-D point P
  const pW = ctr2.clone().addScaledVector(b2.r, state.px).addScaledVector(b2.u, state.py);
  const rayDir = new THREE.Vector3()
    .addScaledVector(b2.r, state.px).addScaledVector(b2.u, state.py).addScaledVector(D2, FOC).normalize();
  const P = C2.clone().addScaledVector(rayDir, state.z);

  // P' = M P, then p' = K P' (normalised by the third coordinate)
  const v = P.clone().sub(C1); const dep = v.dot(d1);
  const valid = dep > 0.05;
  const a = valid ? FOC * v.dot(b1.r) / dep : 0;
  const b = valid ? FOC * v.dot(b1.u) / dep : 0;
  const inside = valid && Math.abs(a) <= HALF && Math.abs(b) <= HALF;
  const ac = THREE.MathUtils.clamp(a, -HALF, HALF), bc = THREE.MathUtils.clamp(b, -HALF, HALF);
  const pp = ctr1.clone().addScaledVector(b1.r, ac).addScaledVector(b1.u, bc);

  Object.assign(geo, { C1, ctr2, ctr1, b2, b1, d1 });
  geo.P.copy(P); geo.pW.copy(pW);

  /* target frame */
  const c2 = corners(ctr2, b2.r, b2.u);
  for (let i = 0; i < 4; i++) { setSeg(edges2[i], c2[i], c2[(i + 1) % 4]); joints2[i].position.copy(c2[i]); }
  fill2.position.copy(ctr2); orient(fill2, b2.r, b2.u, D2);
  setSeg(axis2, C2, ctr2.clone().addScaledVector(D2, 0.55));
  pDot.position.copy(pW); pRim.position.copy(pW); pHit.position.copy(pW);

  /* lift */
  ray2.set(C2, P);
  PDot.position.copy(P); PRim.position.copy(P);
  arcLift.set(pW, P, new THREE.Vector3(-1.8, 0.7, 0.25));

  /* reference frame + motion */
  dot1.position.copy(C1);
  const c1 = corners(ctr1, b1.r, b1.u);
  for (let i = 0; i < 4; i++) { setSeg(edges1[i], c1[i], c1[(i + 1) % 4]); joints1[i].position.copy(c1[i]); }
  fill1.position.copy(ctr1); orient(fill1, b1.r, b1.u, d1);
  setSeg(axis1, C1, ctr1.clone().addScaledVector(d1, 0.55));
  arcRT.set(C2, C1, new THREE.Vector3(0, -1.5, 0));
  loopGroup.position.copy(P);

  /* reprojection */
  ray1.set(P, C1);
  ppDot.position.copy(pp); ppRim.position.copy(pp);
  matRedPP.color.setHex(inside ? COL_RED : COL_OUT);
  arcProj.set(P, pp, new THREE.Vector3(1.1, 0, -1.1));

  /* labels */
  lbl_p.pos.copy(pW);
  lbl_L2.pos.copy(ctr2).addScaledVector(b2.r, 0.74).addScaledVector(b2.u, -0.88);
  lbl_TF.pos.copy(C2).add(new THREE.Vector3(-0.3, -1.05, 0.6));
  lbl_P.pos.copy(P);
  lbl_lift.pos.copy(arcLift.curve.getPoint(0.45));
  lbl_MP.pos.copy(P);
  lbl_RT.pos.copy(arcRT.curve.getPoint(0.5));
  lbl_L1.pos.copy(ctr1).addScaledVector(b1.r, 0.74).addScaledVector(b1.u, -0.88);
  lbl_RF.pos.copy(C1).add(new THREE.Vector3(1.5, -1.05, -0.5));
  lbl_pp.pos.copy(pp);
  lbl_proj.pos.copy(arcProj.curve.getPoint(0.42));

  const fov = document.getElementById('fov');
  fov.textContent = inside ? '' : (valid ? "p’ falls outside ℓ₁ (clamped, greyed)" : "P is behind the reference camera");
}

/* ── stage dimming ───────────────────────────────────────────────────────── */
function setStage(s) {
  state.stage = s;
  STAGES.forEach((g, i) => {
    const on = i <= s;
    g.traverse(o => {
      if (o.material) {
        const base = o.material.userData.base != null ? o.material.userData.base : 1;
        o.material.opacity = on ? base : base * 0.12;
      }
    });
  });
  stageLabels.forEach((arr, i) => arr.forEach(e => { e.div.style.opacity = i <= s ? 1 : 0.13; }));
  for (let i = 0; i < 4; i++) document.getElementById('st' + i).classList.toggle('active', i === s);
}

/* ── build, then frame ───────────────────────────────────────────────────── */
update();
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.72 });
setStage(state.stage);
document.getElementById('btnReset').style.display = '';

/* ── hover / click explanations ──────────────────────────────────────────── */
registerInteractive(pHit, { title: 'Image point p', tooltip: 'Drag me inside ℓ₂', body: 'p is the measured projection of the scene point in the target camera. It fixes only the direction of a ray, not the depth — drag it and watch P and p’ follow.' });
registerInteractive(PDot, { title: '3-D point P', tooltip: 'P = z·K⁻¹p', body: 'Back-projecting p with the calibration K and a depth z gives the 3-D point P = zK⁻¹p. Every z on the slider gives a different P on the same dashed ray.' });
registerInteractive(ppDot, { title: "Reprojected point p’", tooltip: "p’ = K(RP+T)", body: 'The 3-D point expressed in the reference frame (P’ = MP) and projected with K lands here. Matching p’ to a real correspondence is what determines the true depth z.' });
registerInteractive(dot2, { title: 'Target camera centre', tooltip: 'Target camera centre', body: 'All rays of the target camera pass through this optical centre; the thin line is its principal axis.' });
registerInteractive(dot1, { title: 'Reference camera centre', tooltip: 'Reference camera centre', body: 'Related to the target centre by the rigid motion M = [R | T] — the grey arrow along the bottom.' });
registerInteractive(fill2, { title: 'Target image plane ℓ₂', tooltip: 'Image plane ℓ₂', body: 'The image plane sits one focal length f = 1.35 in front of the target centre, perpendicular to the principal axis — a near-vertical square seen obliquely.' });
registerInteractive(fill1, { title: 'Reference image plane ℓ₁', tooltip: 'Image plane ℓ₁', body: 'Same intrinsics K, different pose: its orientation follows R (yaw) and its position follows T.' });

/* ── drag p inside ℓ₂ ────────────────────────────────────────────────────── */
const _ray = new THREE.Raycaster(), _nd = new THREE.Vector2(), _plane = new THREE.Plane(), _hit = new THREE.Vector3();
let dragging = false;
function ndcFrom(e) { const r = canvas.getBoundingClientRect(); _nd.x = ((e.clientX - r.left) / r.width) * 2 - 1; _nd.y = -((e.clientY - r.top) / r.height) * 2 + 1; }
canvas.addEventListener('pointerdown', e => {
  ndcFrom(e); _ray.setFromCamera(_nd, camera);
  if (_ray.intersectObject(pHit, false).length) {
    dragging = true; controls.enabled = false;
    try { canvas.setPointerCapture(e.pointerId); } catch (err) { }
  }
}, true);
canvas.addEventListener('pointermove', e => {
  if (!dragging) return;
  ndcFrom(e); _ray.setFromCamera(_nd, camera);
  _plane.setFromNormalAndCoplanarPoint(D2, geo.ctr2);
  if (_ray.ray.intersectPlane(_plane, _hit)) {
    const v = _hit.clone().sub(geo.ctr2);
    state.px = THREE.MathUtils.clamp(v.dot(geo.b2.r), -HALF, HALF);
    state.py = THREE.MathUtils.clamp(v.dot(geo.b2.u), -HALF, HALF);
    stopDemo(); update();
  }
}, true);
window.addEventListener('pointerup', () => { if (dragging) { dragging = false; controls.enabled = true; } });

/* ── sliders ─────────────────────────────────────────────────────────────── */
const sZ = document.getElementById('sZ'), sY = document.getElementById('sY'),
  sX = document.getElementById('sX'), sTz = document.getElementById('sTz');
const vZ = document.getElementById('vZ'), vY = document.getElementById('vY'),
  vX = document.getElementById('vX'), vTz = document.getElementById('vTz');
function syncUI() {
  sZ.value = state.z; vZ.textContent = state.z.toFixed(2);
  sY.value = state.yaw; vY.textContent = state.yaw.toFixed(0);
  sX.value = state.tx; vX.textContent = state.tx.toFixed(2);
  sTz.value = state.tz; vTz.textContent = state.tz.toFixed(2);
}
syncUI();
sZ.addEventListener('input', () => { state.z = +sZ.value; stopDemo(); syncUI(); update(); });
sY.addEventListener('input', () => { state.yaw = +sY.value; stopDemo(); syncUI(); update(); });
sX.addEventListener('input', () => { state.tx = +sX.value; stopDemo(); syncUI(); update(); });
sTz.addEventListener('input', () => { state.tz = +sTz.value; stopDemo(); syncUI(); update(); });
for (let i = 0; i < 4; i++) document.getElementById('st' + i).addEventListener('click', () => { stopDemo(); setStage(i); });

/* ── demo ────────────────────────────────────────────────────────────────── */
const steps = [
  { title: 'The measurement p', narration: 'Only the target camera, its image plane ℓ₂ and the measured red point p are active. A single image point is all the sensor gives you.', st: 0, z: 5.5, yaw: 20, tx: 2.8, tz: -1.4 },
  { title: 'Back-project: P = zK⁻¹p', narration: 'The dashed ray fires out from the camera centre through p. Sliding depth z walks P along that ray — the image alone cannot decide which P is correct.', st: 1, z: 6.8, yaw: 20, tx: 2.8, tz: -1.4 },
  { title: 'Rigid motion: P’ = MP', narration: 'The loop at P applies M = [R | T], expressing the same 3-D point in the reference camera’s frame. Changing the baseline or yaw changes M, not the point in space.', st: 2, z: 6.8, yaw: 30, tx: 3.4, tz: -1.4 },
  { title: 'Reproject: p’ = KP', narration: 'The second dashed line carries P into the reference plane ℓ₁ at p’. Sweep z again: p is frozen but p’ slides — matching that sliding point to a real correspondence is what recovers depth.', st: 3, z: 4.9, yaw: 30, tx: 3.4, tz: -1.4 }
];
let stepIdx = 0, tween = null, playing = false, playT = 0;
const narr = document.getElementById('narr'), bPlay = document.getElementById('bPlay');

function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  narr.innerHTML = '<b>' + (stepIdx + 1) + '. ' + s.title + '</b><br>' + s.narration;
  setStage(s.st);
  tween = { t: 0, from: { z: state.z, yaw: state.yaw, tx: state.tx, tz: state.tz }, to: { z: s.z, yaw: s.yaw, tx: s.tx, tz: s.tz } };
}
function stopDemo() { playing = false; tween = null; bPlay.textContent = '▶ Play demo'; bPlay.classList.remove('active'); }
document.getElementById('bPrev').addEventListener('click', () => { playing = false; bPlay.textContent = '▶ Play demo'; bPlay.classList.remove('active'); goToStep(stepIdx - 1); });
document.getElementById('bNext').addEventListener('click', () => { playing = false; bPlay.textContent = '▶ Play demo'; bPlay.classList.remove('active'); goToStep(stepIdx + 1); });
bPlay.addEventListener('click', () => {
  playing = !playing;
  bPlay.textContent = playing ? '❚❚ Pause' : '▶ Play demo';
  bPlay.classList.toggle('active', playing);
  if (playing) { playT = 0; goToStep(0); }
});

/* ── own animation tick: tweening + billboarding the self-loop ───────────── */
let _last = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(64, now - _last); _last = now;
  if (tween) {
    tween.t = Math.min(1, tween.t + dt / 900);
    const t = tween.t, k = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    const f = tween.from, g2 = tween.to;
    state.z = f.z + (g2.z - f.z) * k;
    state.yaw = f.yaw + (g2.yaw - f.yaw) * k;
    state.tx = f.tx + (g2.tx - f.tx) * k;
    state.tz = f.tz + (g2.tz - f.tz) * k;
