────────────────────────────────────────────────────────────────────────────── */

const YA = new THREE.Vector3(0, 1, 0);
const COL_BLACK = 0x000000, COL_RED = 0xC0141B, COL_GREY = 0x9A9A9A, COL_OUT = 0x9aa0a6;

const C2 = new THREE.Vector3(-3.4, -1.5, 0.9);
// principal axis: mostly -Z (which reads as "up and to the right" in this
