// image plane projects to the source's tall parallelogram.
const D2 = new THREE.Vector3(0.138, 0.217, -0.966).normalize();
const FOC = 1.5;       // focal length = plane distance (K = diag(f,f,1))
const HALF = 1.45;     // half side of the 2.9 x 2.9 image square

const state = { px: -0.45, py: 0.55, z: 5.0, yaw: 30, tx: 3.6, tz: -1.2, stage: 3 };

/* ── helpers ─────────────────────────────────────────────────────────────── */
function basis(dv) {
  const r = new THREE.Vector3().crossVectors(dv, YA).normalize();
  const u = new THREE.Vector3().crossVectors(r, dv).normalize();
  return { r, u };
}
function M(color, opacity = 1, o = {}) {
  const m = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity,
    depthTest: false, depthWrite: false,
    side: o.side || THREE.FrontSide
  });
  m.userData.base = opacity;
  return m;
}
function RO(obj, n) { obj.traverse(o => { o.renderOrder = n; }); return obj; }

const UNIT_CYL = new THREE.CylinderGeometry(1, 1, 1, 12);
UNIT_CYL.translate(0, 0.5, 0);
function segMesh(material, radius) { const m = new THREE.Mesh(UNIT_CYL, material); m.userData.rad = radius; return m; }
function setSeg(m, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
  if (len < 1e-5) { m.visible = false; m.scale.set(0, 0, 0); return; }
  m.visible = true; m.position.copy(a);
  m.quaternion.setFromUnitVectors(YA, dir.divideScalar(len));
  m.scale.set(m.userData.rad, len, m.userData.rad);
}
function makeDash(material, radius, maxN) {
  const g = new THREE.Group(); const arr = [];
  for (let i = 0; i < maxN; i++) { const m = segMesh(material, radius); m.visible = false; m.scale.set(0, 0, 0); g.add(m); arr.push(m); }
  return {
    group: g,
    set(a, b, dash = 0.30, gap = 0.22) {
      const dir = new THREE.Vector3().subVectors(b, a); const len = dir.length();
      if (len < 1e-5) { arr.forEach(m => { m.visible = false; m.scale.set(0, 0, 0); }); return; }
      dir.divideScalar(len);
      const per = dash + gap, n = Math.max(1, Math.floor((len + gap) / per));
      for (let i = 0; i < arr.length; i++) {
        if (i < n) {
          const s = a.clone().addScaledVector(dir, i * per);
