}
/* Curved annotation arrow. The bulge direction is orthogonalised against the
   chord, so the control point is a genuine perpendicular offset — that is what
   keeps the arc a clean circular-looking sweep instead of a lopsided teardrop. */
function makeArc(material) {
  const tube = new THREE.Mesh(new THREE.BufferGeometry(), material);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.135, 0.36, 16), material);
  const g = new THREE.Group(); g.add(tube, head);
  return {
    group: g, curve: null,
    set(a0, b0, dirRaw, sag = 0.18, trimA = 0.30, trimB = 0.34) {
      const chord = new THREE.Vector3().subVectors(b0, a0);
      const L = Math.max(chord.length(), 1e-4);
      const cu = chord.clone().divideScalar(L);
      const a = a0.clone().addScaledVector(cu, Math.min(trimA, L * 0.28));
      const b = b0.clone().addScaledVector(cu, -Math.min(trimB, L * 0.28));
      const n = dirRaw.clone().addScaledVector(cu, -dirRaw.dot(cu));
      if (n.lengthSq() < 1e-6) n.set(0, 1, 0).addScaledVector(cu, -cu.y);
