      const mid = a.clone().add(b).multiplyScalar(0.5).addScaledVector(n, 2 * sag * L);
      const curve = new THREE.QuadraticBezierCurve3(a, mid, b);
      const tEnd = 0.87, pts = [];
      for (let i = 0; i <= 44; i++) pts.push(curve.getPoint(tEnd * i / 44));
      tube.geometry.dispose();
      tube.geometry = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 44, 0.038, 10, false);
      const tan = curve.getTangent(1).normalize();
      head.position.copy(curve.getPoint(1)).addScaledVector(tan, -0.18);
