/* ── stage groups ────────────────────────────────────────────────────────── */
const gT = new THREE.Group(), gL = new THREE.Group(), gM = new THREE.Group(), gP = new THREE.Group();
scene.add(gT, gL, gM, gP);
const STAGES = [gT, gL, gM, gP];
const stageLabels = [[], [], [], []];

/* ── materials ───────────────────────────────────────────────────────────── */
const matEdge2 = M(COL_BLACK), matEdge1 = M(COL_BLACK);
const matFill2 = M(0xffffff, 0.05, { side: THREE.DoubleSide }), matFill1 = M(0xffffff, 0.05, { side: THREE.DoubleSide });
const matAxis2 = M(COL_BLACK), matAxis1 = M(COL_BLACK);
const matDot = M(COL_BLACK), matDot1 = M(COL_BLACK);
const matRed = M(COL_RED), matRedP = M(COL_RED), matRedPP = M(COL_RED);
const matRim = M(0x000000, 1, { side: THREE.BackSide });
const matRay2 = M(COL_BLACK), matRay1 = M(COL_BLACK);
const matArc1 = M(COL_GREY), matArc3 = M(COL_GREY), matArcRT = M(COL_GREY), matLoop = M(COL_GREY);

/* ── stage 0 : target frame ──────────────────────────────────────────────── */
