dot2.position.copy(C2);
const edges2 = [0, 1, 2, 3].map(() => { const m = segMesh(matEdge2, 0.030); gT.add(m); return m; });
const joints2 = [0, 1, 2, 3].map(() => { const m = new THREE.Mesh(new THREE.SphereGeometry(0.030, 10, 8), matEdge2); gT.add(m); return m; });
const fill2 = new THREE.Mesh(new THREE.PlaneGeometry(2 * HALF, 2 * HALF), matFill2); gT.add(fill2);
const axis2 = segMesh(matAxis2, 0.015); gT.add(axis2);
const pDot = new THREE.Mesh(new THREE.SphereGeometry(0.15, 22, 16), matRed); gT.add(pDot);
const pRim = new THREE.Mesh(new THREE.SphereGeometry(0.178, 22, 16), matRim); gT.add(pRim);
const pHit = new THREE.Mesh(new THREE.SphereGeometry(0.36, 12, 10),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false, depthTest: false }));
pHit.material.userData.base = 0; gT.add(pHit);

/* ── stage 1 : lift to 3-D ───────────────────────────────────────────────── */
const ray2 = makeDash(matRay2, 0.028, 70); gL.add(ray2.group);
const PDot = new THREE.Mesh(new THREE.SphereGeometry(0.15, 22, 16), matRedP); gL.add(PDot);
const PRim = new THREE.Mesh(new THREE.SphereGeometry(0.178, 22, 16), matRim); gL.add(PRim);
const arcLift = makeArc(matArc1); gL.add(arcLift.group);

/* ── stage 2 : rigid motion + reference camera ───────────────────────────── */
const dot1 = new THREE.Mesh(new THREE.SphereGeometry(0.13, 22, 16), matDot1); gM.add(dot1);
const edges1 = [0, 1, 2, 3].map(() => { const m = segMesh(matEdge1, 0.030); gM.add(m); return m; });
const joints1 = [0, 1, 2, 3].map(() => { const m = new THREE.Mesh(new THREE.SphereGeometry(0.030, 10, 8), matEdge1); gM.add(m); return m; });
const fill1 = new THREE.Mesh(new THREE.PlaneGeometry(2 * HALF, 2 * HALF), matFill1); gM.add(fill1);
const axis1 = segMesh(matAxis1, 0.015); gM.add(axis1);
const arcRT = makeArc(matArcRT); gM.add(arcRT.group);

// self-loop above P, built once in its own billboard plane
const loopGroup = new THREE.Group(); gM.add(loopGroup);
{
  const R = 0.66, cy = 0.82, a0 = THREE.MathUtils.degToRad(240), a1 = THREE.MathUtils.degToRad(-38);
  const pts = [];
  for (let i = 0; i <= 72; i++) { const th = a0 + (a1 - a0) * i / 72; pts.push(new THREE.Vector3(R * Math.cos(th), cy + R * Math.sin(th), 0)); }
  const tube = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 72, 0.038, 10, false), matLoop);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.135, 0.36, 16), matLoop);
  const tan = new THREE.Vector3(Math.sin(a1), -Math.cos(a1), 0).normalize();
  head.position.set(R * Math.cos(a1), cy + R * Math.sin(a1), 0).addScaledVector(tan, 0.08);
