}

/* ── stage 3 : reprojection ──────────────────────────────────────────────── */
const ray1 = makeDash(matRay1, 0.028, 80); gP.add(ray1.group);
const ppDot = new THREE.Mesh(new THREE.SphereGeometry(0.15, 22, 16), matRedPP); gP.add(ppDot);
const ppRim = new THREE.Mesh(new THREE.SphereGeometry(0.178, 22, 16), matRim); gP.add(ppRim);
const arcProj = makeArc(matArc3); gP.add(arcProj.group);

/* ── draw order (everything depthTest:false → painter ordering) ──────────── */
RO(fill2, -3); RO(fill1, -3);
RO(arcLift.group, -1); RO(arcProj.group, -1); RO(arcRT.group, -1); RO(loopGroup, -1);
edges2.forEach(m => RO(m, 1)); edges1.forEach(m => RO(m, 1));
joints2.forEach(m => RO(m, 1)); joints1.forEach(m => RO(m, 1));
RO(axis2, 1); RO(axis1, 1);
RO(ray2.group, 2); RO(ray1.group, 2);
RO(pRim, 4); RO(PRim, 4); RO(ppRim, 4);
RO(pDot, 5); RO(PDot, 5); RO(ppDot, 5); RO(dot2, 5); RO(dot1, 5);

/* ── labels (sized to the source's bold serif lettering) ─────────────────── */
const SER = t => '<span style="font-family:Georgia,\'Times New Roman\',serif">' + t + '</span>';
const FS_PT = '26px', FS_EQ = '19px', FS_L = '31px', FS_FR = '23px';
const O = new THREE.Vector3();
function L(html, stage, opts) { const e = addLabel(html, O, opts); stageLabels[stage].push(e); return e; }

const lbl_p = L(SER('<b>p</b>'), 0, { fontSize: FS_PT, offset: [-30, -20] });
const lbl_L2 = L(SER('<i>&#8467;</i><sub>2</sub>'), 0, { fontSize: FS_L, offset: [0, 0] });
const lbl_TF = L(SER('Target frame'), 0, { fontSize: FS_FR, offset: [0, 0] });

const lbl_P = L(SER('<b>P</b>'), 1, { fontSize: FS_PT, offset: [-32, -22] });
const lbl_lift = L(SER('<b>P</b>=z<b>K</b><sup>-1</sup><b>p</b>'), 1, { fontSize: FS_EQ, offset: [-62, -18] });

const lbl_MP = L(SER('<b>P</b>’=<b>MP</b>'), 2, { fontSize: FS_EQ, offset: [86, 24] });
const lbl_RT = L(SER('<b>R</b>, <b>T</b>'), 2, { fontSize: FS_EQ, offset: [0, 34] });
const lbl_L1 = L(SER('<i>&#8467;</i><sub>1</sub>'), 2, { fontSize: FS_L, offset: [0, 0] });
const lbl_RF = L(SER('Reference frame'), 2, { fontSize: FS_FR, offset: [0, 0] });

const lbl_pp = L(SER('<b>p</b>’'), 3, { fontSize: FS_PT, offset: [2, 30] });
const lbl_proj = L(SER('<b>p</b>’=<b>KP</b>'), 3, { fontSize: FS_EQ, offset: [76, -4] });

/* ── the whole chain, recomputed from the controls ───────────────────────── */
const geo = { ctr2: new THREE.Vector3(), b2: null, P: new THREE.Vector3() };

function corners(c, r, u) {
  return [
    c.clone().addScaledVector(r, -HALF).addScaledVector(u, HALF),
    c.clone().addScaledVector(r, HALF).addScaledVector(u, HALF),
    c.clone().addScaledVector(r, HALF).addScaledVector(u, -HALF),
    c.clone().addScaledVector(r, -HALF).addScaledVector(u, -HALF)
