}
function orient(mesh, r, u, n) {
  mesh.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(r, u, n));
}

function update() {
  const yaw = THREE.MathUtils.degToRad(state.yaw);
  const d1 = D2.clone().applyAxisAngle(YA, yaw);
  const C1 = new THREE.Vector3(C2.x + state.tx, C2.y, C2.z + state.tz);
  const b2 = basis(D2), b1 = basis(d1);
  const ctr2 = C2.clone().addScaledVector(D2, FOC);
  const ctr1 = C1.clone().addScaledVector(d1, FOC);

  // measured image point p and the back-projected 3-D point P = z K^-1 p
  const pW = ctr2.clone().addScaledVector(b2.r, state.px).addScaledVector(b2.u, state.py);
  const rayDir = new THREE.Vector3()
    .addScaledVector(b2.r, state.px).addScaledVector(b2.u, state.py).addScaledVector(D2, FOC).normalize();
