  /* labels */
  lbl_p.pos.copy(pW);
  lbl_L2.pos.copy(ctr2).addScaledVector(b2.r, 0.95).addScaledVector(b2.u, -1.05);
  lbl_TF.pos.copy(C2).add(new THREE.Vector3(-0.3, -0.95, 0.8));
