  lbl_MP.pos.copy(P);
  lbl_RT.pos.copy(arcRT.curve.getPoint(0.5));
  lbl_L1.pos.copy(ctr1).addScaledVector(b1.r, 0.95).addScaledVector(b1.u, -1.05);
  lbl_RF.pos.copy(C1).add(new THREE.Vector3(1.9, -0.95, -0.2));
  lbl_pp.pos.copy(pp);
  lbl_proj.pos.copy(arcProj.curve.getPoint(0.30));

  const fov = document.getElementById('fov');
  fov.textContent = inside ? '' : (valid ? 'p’ falls outside ℓ₁ (clamped, greyed)' : 'P is behind the reference camera');
}

/* ── stage dimming ───────────────────────────────────────────────────────── */
const stageText = [
  ['The measurement p', 'Only the target camera, its image plane ℓ₂ and the measured red point p. A single image point is all the sensor gives you.'],
  ['Back-project: P = zK⁻¹p', 'The dashed ray leaves the camera centre through p. Depth z slides P along that ray — one image cannot pick the right one.'],
  ['Rigid motion: P’ = MP', 'The grey loop applies M = [R | T]: the same 3-D point, now written in the reference camera’s frame.'],
  ['Reproject: p’ = KP', 'Projecting into ℓ₁ gives p’. Sweep z: p is frozen while p’ slides — matching p’ to a real correspondence recovers depth.']
];
function setStage(s, quiet) {
  state.stage = s;
  STAGES.forEach((g, i) => {
    const on = i <= s;
    g.traverse(o => {
      if (o.material) {
        const base = o.material.userData.base != null ? o.material.userData.base : 1;
        o.material.opacity = on ? base : base * 0.12;
      }
    });
  });
  stageLabels.forEach((arr, i) => arr.forEach(e => { e.div.style.opacity = i <= s ? 1 : 0.13; }));
  for (let i = 0; i < 4; i++) document.getElementById('st' + i).classList.toggle('active', i === s);
  if (!quiet) {
    const t = stageText[s];
    document.getElementById('narr').innerHTML = '<b>' + t[0] + '</b><br>' + t[1];
  }
}

