registerInteractive(pHit, { title: 'Image point p', tooltip: 'Drag me inside ℓ₂', body: 'p is the measured projection of the scene point in the target camera. It fixes only the direction of a ray, not the depth — drag it and watch P and p’ follow.' });
registerInteractive(PDot, { title: '3-D point P', tooltip: 'P = z·K⁻¹p', body: 'Back-projecting p with the calibration K and a depth z gives P = zK⁻¹p. Every z on the slider gives a different P on the same dashed ray.' });
registerInteractive(ppDot, { title: 'Reprojected point p’', tooltip: 'p’ = K(RP+T)', body: 'The 3-D point expressed in the reference frame (P’ = MP) and projected with K lands here. Matching p’ to a real correspondence is what determines the true depth z.' });
