/* ── drag p inside ℓ₂ ────────────────────────────────────────────────────── */
const _ray = new THREE.Raycaster(), _nd = new THREE.Vector2(), _plane = new THREE.Plane(), _hit = new THREE.Vector3();
let dragging = false;
function ndcFrom(e) { const r = canvas.getBoundingClientRect(); _nd.x = ((e.clientX - r.left) / r.width) * 2 - 1; _nd.y = -((e.clientY - r.top) / r.height) * 2 + 1; }
canvas.addEventListener('pointerdown', e => {
  ndcFrom(e); _ray.setFromCamera(_nd, camera);
  if (_ray.intersectObject(pHit, false).length) {
    dragging = true; controls.enabled = false;
    try { canvas.setPointerCapture(e.pointerId); } catch (err) { }
  }
}, true);
canvas.addEventListener('pointermove', e => {
  if (!dragging) return;
  ndcFrom(e); _ray.setFromCamera(_nd, camera);
  _plane.setFromNormalAndCoplanarPoint(D2, geo.ctr2);
  if (_ray.ray.intersectPlane(_plane, _hit)) {
    const v = _hit.clone().sub(geo.ctr2);
    state.px = THREE.MathUtils.clamp(v.dot(geo.b2.r), -HALF, HALF);
    state.py = THREE.MathUtils.clamp(v.dot(geo.b2.u), -HALF, HALF);
    stopDemo(); update();
  }
}, true);
window.addEventListener('pointerup', () => { if (dragging) { dragging = false; controls.enabled = true; } });

/* ── sliders ─────────────────────────────────────────────────────────────── */
const sZ = document.getElementById('sZ'), sY = document.getElementById('sY'),
  sX = document.getElementById('sX'), sTz = document.getElementById('sTz');
const vZ = document.getElementById('vZ'), vY = document.getElementById('vY'),
  vX = document.getElementById('vX'), vTz = document.getElementById('vTz');
function syncUI() {
  sZ.value = state.z; vZ.textContent = state.z.toFixed(2);
  sY.value = state.yaw; vY.textContent = state.yaw.toFixed(0);
  sX.value = state.tx; vX.textContent = state.tx.toFixed(2);
  sTz.value = state.tz; vTz.textContent = state.tz.toFixed(2);
}
syncUI();
sZ.addEventListener('input', () => { state.z = +sZ.value; stopDemo(); syncUI(); update(); });
sY.addEventListener('input', () => { state.yaw = +sY.value; stopDemo(); syncUI(); update(); });
