/* ── demo ────────────────────────────────────────────────────────────────── */
const steps = [
  { title: 'The measurement p', narration: 'Only the target camera, its image plane ℓ₂ and the measured red point p are active. A single image point is all the sensor gives you.', st: 0, z: 5.0, yaw: 30, tx: 3.6, tz: -1.2 },
  { title: 'Back-project: P = zK⁻¹p', narration: 'The dashed ray fires out from the camera centre through p. Sliding depth z walks P along that ray — the image alone cannot decide which P is correct.', st: 1, z: 6.6, yaw: 30, tx: 3.6, tz: -1.2 },
  { title: 'Rigid motion: P’ = MP', narration: 'The loop at P applies M = [R | T], expressing the same 3-D point in the reference camera’s frame. Changing the baseline or yaw changes M, not the point in space.', st: 2, z: 6.6, yaw: 42, tx: 4.3, tz: -1.2 },
  { title: 'Reproject: p’ = KP', narration: 'The second dashed line carries P into the reference plane ℓ₁ at p’. Sweep z again: p is frozen but p’ slides — matching that sliding point to a real correspondence is what recovers depth.', st: 3, z: 4.2, yaw: 42, tx: 4.3, tz: -1.2 }
];
let stepIdx = 0, tween = null, playing = false, playT = 0;
const narr = document.getElementById('narr'), bPlay = document.getElementById('bPlay');

function goToStep(i) {
  stepIdx = ((i % steps.length) + steps.length) % steps.length;
  const s = steps[stepIdx];
  setStage(s.st, true);
  narr.innerHTML = '<b>' + (stepIdx + 1) + '. ' + s.title + '</b><br>' + s.narration;
  tween = { t: 0, from: { z: state.z, yaw: state.yaw, tx: state.tx, tz: state.tz }, to: { z: s.z, yaw: s.yaw, tx: s.tx, tz: s.tz } };
}
function stopDemo() { playing = false; tween = null; bPlay.textContent = '▶ Play demo'; bPlay.classList.remove('active'); }
document.getElementById('bPrev').addEventListener('click', () => { playing = false; bPlay.textContent = '▶ Play demo'; bPlay.classList.remove('active'); goToStep(stepIdx - 1); });
document.getElementById('bNext').addEventListener('click', () => { playing = false; bPlay.textContent = '▶ Play demo'; bPlay.classList.remove('active'); goToStep(stepIdx + 1); });
bPlay.addEventListener('click', () => {
  playing = !playing;
  bPlay.textContent = playing ? '❚❚ Pause' : '▶ Play demo';
  bPlay.classList.toggle('active', playing);
  if (playing) { playT = 0; goToStep(0); }
});

/* ── own tick: tweening + billboarding the self-loop ─────────────────────── */
let _last = performance.now();
function tick(now) {
  requestAnimationFrame(tick);
  const dt = Math.min(64, now - _last); _last = now;
  if (tween) {
    tween.t = Math.min(1, tween.t + dt / 900);
    const t = tween.t, k = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    const f = tween.from, g2 = tween.to;
    state.z = f.z + (g2.z - f.z) * k;
    state.yaw = f.yaw + (g2.yaw - f.yaw) * k;
    state.tx = f.tx + (g2.tx - f.tx) * k;
    state.tz = f.tz + (g2.tz - f.tz) * k;
    syncUI(); update();
    if (tween.t >= 1) tween = null;
  }
  if (playing) { playT += dt; if (playT > 3800) { playT = 0; goToStep(stepIdx + 1); } }
  loopGroup.quaternion.copy(camera.quaternion);
}
requestAnimationFrame(tick);
